// Drops null/undefined items and returns each item's `n`, uppercased when `a == 1`.
function proc(items) {
  return items
    .filter((item) => item != null)
    .map((item) => (item.a == 1 ? item.n.toUpperCase() : item.n));
}

// Splits a comma-separated string into trimmed, non-empty parts.
function f2(csv) {
  return csv
    .split(',')
    .map((part) => part.trim())
    .filter(Boolean);
}

module.exports = { proc, f2 };

if (require.main === module) {
  const assert = require('assert');
  assert.deepStrictEqual(proc([{ a: 1, n: 'x' }, null, undefined, { a: 0, n: 'y' }, { a: '1', n: 'z' }]), ['X', 'y', 'Z']);
  assert.deepStrictEqual(f2(' a, b ,, ,c '), ['a', 'b', 'c']);
  console.log('ok');
}

